// BacktestSignal Judges each signal candle's close, and every evaluated candle's
// alike, by a stop and a target over the window candles after it. The
// stop lies one ATR(14) from the close against the expected move.
// ATR uses Wilder-smoothed true ranges through the signal candle,
// including shadows and price gaps. The distance does not depend on
// the window, which only limits evaluation time. The
// target lies target_ratio stops away in the expected direction; a
// sideways signal has a target on both sides and no stop. Outcomes may
// read stored candles after the evaluated period.
type BacktestSignal struct {
	// All Every evaluated candle with an evaluation.
	All BacktestSignalStats `json:"all"`

	// Evaluated Entry signals with an evaluation.
	Evaluated int `json:"evaluated"`

	// Occurrences Entry signals, oldest first.
	Occurrences []BacktestSignalOccurrence `json:"occurrences"`

	// Signals The counted entry signals, each at least a window after the previous counted one.
	Signals BacktestSignalStats `json:"signals"`

	// TargetRatio Target distance in stops.
	TargetRatio int `json:"target_ratio"`

	// Window Candles after the signal candle that are judged.
	Window int `json:"window"`
}

// BacktestSignalOccurrence An entry signal. counted, stop, target, move, outcome, and exit_time are null
// together when history lacks a positive ATR(14), the full consecutive
// future window, or valid positive-price levels. ATR needs at least
// 14 preceding consecutive candles and restarts after missing candles.
// Histories of at least 2,000 candles may have lost older seed candles:
// their initial evaluations also wait for the shared indicator warm-up
// (150 candles including the signal for ATR(14)).
type BacktestSignalOccurrence struct {
	Close float64 `json:"close"`

	// Counted Whether the statistics count the signal; a signal within a window after the previous counted one is a repeat.
	Counted *bool `json:"counted"`

	// ExitTime Open time of the first candle deciding the outcome (target or stop), or the last candle of the window if no level is touched. Null without evaluation.
	ExitTime *time.Time `json:"exit_time"`

	// IndicatorValues Current local indicator outputs at signal close, keyed by indicator_columns; unknown outputs are omitted.
	IndicatorValues map[string]float64 `json:"indicator_values"`

	// Move Largest move from the close in the expected direction, also after
	// the target, until the stop is reached or the window ends; for
	// sideways the largest move in either direction.
	Move *float64 `json:"move"`

	// Outcome Target before stop is success; stop first is failure. Without either
	// touch, the final close at least one ATR in the expected direction is
	// success, from entry to less than one ATR is neutral, and against the
	// direction is failure. Sideways keeps its target-touch rule without
	// neutral outcomes. Null means insufficient history for evaluation.
	Outcome *BacktestSignalOutcome `json:"outcome"`

	// Stop One ATR(14) divided by the signal close, as a fraction; null for sideways or an unevaluated signal.
	Stop *float64 `json:"stop"`

	// Target target_ratio times ATR(14) divided by the signal close, as a fraction; on both sides for sideways, null for an unevaluated signal.
	Target *float64 `json:"target"`

	// Time Open time of the candle whose close signaled.
	Time time.Time `json:"time"`

	// Values What the entry rule read at the signal.
	Values BacktestValues `json:"values"`
}

